import csv
import io

_FIELDS = ('sku', 'name', 'qty')
_DIGITS = set('0123456789')


def _parse_row(row):
    values = {}
    for field in _FIELDS:
        raw = row.get(field)
        if raw is None:
            raise ValueError('row is missing field %r' % field)
        values[field] = raw.strip()
    if not values['sku']:
        raise ValueError('sku must be nonempty after trimming')
    if not values['name']:
        raise ValueError('name must be nonempty after trimming')
    if not values['qty'].strip() or not all(c in _DIGITS for c in values['qty']):
        raise ValueError('qty must contain only decimal digits')
    values['qty'] = int(values['qty'])
    return values


def import_text(text, store, dry_run=False):
    rows = list(csv.DictReader(io.StringIO(text)))
    items = [_parse_row(row) for row in rows]

    result = {'created': 0, 'updated': 0, 'unchanged': 0, 'changes': []}
    to_commit = []
    for item in items:
        before = store.get(item['sku'])
        if before == item:
            result['unchanged'] += 1
            continue
        result['created' if before is None else 'updated'] += 1
        result['changes'].append({'sku': item['sku'], 'before': before, 'after': item})
        to_commit.append(item)

    if not dry_run:
        for item in to_commit:
            store.put(item)
    return result

